# name: trial_drift_yes_rate
# description: Yes-rate on trials in the second half of a session (trial_index >= median) minus the first half; observed > null means people become more liberal over the session, a drift the stationary model does not produce.
def test_statistic(df):
    ti = df["trial_index"].astype(float).to_numpy()
    y = df["rating"].astype(float).to_numpy()
    late = ti >= np.median(ti)
    if late.all() or (~late).all():
        return 0.0
    return float(y[late].mean() - y[~late].mean())

# name: between_set_yes_rate_sd
# description: Standard deviation across distinct sets of the per-set yes-rate (sets with >= 20 responses); observed > null means human generalization breadth varies more across sets than the model predicts (some sets far broader/narrower), observed < null means the model over-differentiates sets.
def test_statistic(df):
    g = df.groupby("number_set")["rating"].agg(["mean", "size"])
    g = g[g["size"] >= 20]
    if len(g) < 2:
        return 0.0
    return float(g["mean"].std())
